<?php if (isset($card['quota']) && is_int($card['quota'])): ?><div><dt>할부</dt><dd><?= $card['quota'] === 0 ? '일시불' : $card['quota'] . '개월' ?><?= !empty($card['interest_free']) ? ' · 무이자' : '' ?></dd></div><?php endif ?>
